(()=>{
'use strict';
const U='https://gfggmkeucgqkkyvummpu.supabase.co',K='sb_publishable_ptCVbq9h15prKhT0OO5Zmg_LkE3cbK0';
const esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]));
const api=async p=>{const r=await fetch(U+p,{headers:{apikey:K,Authorization:`Bearer ${K}`,Accept:'application/json'}});const t=await r.text();let d=null;try{d=t?JSON.parse(t):null}catch{}if(!r.ok)throw new Error(d?.message||`HTTP ${r.status}`);return d||[]};
const old=window.render;
function wire(){document.querySelectorAll('#home [data-view]').forEach(b=>b.onclick=()=>window.render?.(b.dataset.view));try{window.lucide?.createIcons()}catch{}}
async function loadProblems(){const box=document.getElementById('cleanIssues');if(!box)return;try{const rows=await api('/rest/v1/problems?select=id,title,category,status,updated_at,region_id&order=updated_at.desc&limit=4');if(!rows.length){box.innerHTML='<div class="clean-empty">Belum ada masalah publik yang tersedia.</div>';return}box.innerHTML=rows.map((x,i)=>`<button data-problem="${esc(x.id)}"><i>${['🛣️','🛒','🏫','🌧️'][i%4]}</i><div><b>${esc(x.title)}</b><span>${esc(x.category||'Masalah')} · ${esc(x.status||'tercatat')} · ${x.updated_at?new Date(x.updated_at).toLocaleDateString('id-ID'):''}</span></div><em>Lihat detail →</em></button>`).join('');box.querySelectorAll('[data-problem]').forEach(b=>b.onclick=()=>window.render?.('problem-detail',b.dataset.problem))}catch(e){box.innerHTML='<div class="clean-empty">Data masalah belum dapat dimuat. Buka “Masalah” untuk mencoba lagi.</div>'}}
function refreshHome(){const map=document.querySelector('.clean-map-placeholder');if(map)map.innerHTML='<div class="clean-map-real"><div id="homeIndonesiaMap"></div></div><p class="clean-map-caption">Peta publik. Klik provinsi untuk membuka wilayah.</p>';const cats=document.querySelector('.clean-cats');if(cats)cats.innerHTML=['Ekonomi','Sosial','Kesehatan','Pendidikan','Infrastruktur','Lingkungan'].map(x=>`<button data-view="problems">${x}<span>Lihat masalah →</span></button>`).join('');const alerts=document.querySelector('.clean-alerts');if(alerts)alerts.innerHTML='<li><b>•</b> Pantauan perubahan tersedia berdasarkan masalah publik yang tersimpan.</li><li><b>•</b> Gunakan detail masalah untuk melihat status dan konteks.</li><li><b>•</b> Laporan warga dipisahkan dari fakta yang telah diverifikasi.</li>';wire();loadProblems();setTimeout(()=>window.dispatchEvent(new Event('load')),50)}
const render=window.render;
window.render=async function(v,x=''){if(v==='home'){const r=await (typeof render==='function'?render(v,x):undefined);setTimeout(refreshHome,20);return r}return typeof render==='function'?render(v,x):undefined};
document.addEventListener('DOMContentLoaded',()=>setTimeout(refreshHome,30));
})();
